-- Generated by dbt/sync_models.py from sql/staging/stg_products.sql. Do not edit.
-- One row per product_id. Category normalised and translated; the two categories missing
-- from the source translation table come from config/category_translation_extra.csv.
-- A missing category stays NULL here; KPIs map it to the unknown label (KPI decision 4).
-- Fixes the source typo product_name_lenght -> product_name_length.
WITH translation AS (
    SELECT lower(trim(product_category_name))         AS category_pt,
           lower(trim(product_category_name_english)) AS category_en
    FROM {{ source('raw', 'product_category_name_translation') }}
    UNION
    SELECT lower(trim(product_category_name)), lower(trim(product_category_name_english))
    FROM {{ ref('category_translation_extra') }}
)
SELECT p.product_id,
       lower(trim(p.product_category_name))              AS category_pt,
       t.category_en,
       TRY_CAST(p.product_name_lenght AS INTEGER)        AS product_name_length,
       TRY_CAST(p.product_description_lenght AS INTEGER) AS product_description_length,
       TRY_CAST(p.product_photos_qty AS INTEGER)         AS product_photos_qty,
       TRY_CAST(p.product_weight_g AS DOUBLE)            AS product_weight_g
FROM {{ source('raw', 'products') }} p
LEFT JOIN translation t ON t.category_pt = lower(trim(p.product_category_name))
QUALIFY row_number() OVER (PARTITION BY p.product_id ORDER BY t.category_en) = 1
ORDER BY product_id
